import React, { useState } from "react";
import axios from "axios";

const OurClients = () => {
  // Variable for client logo
  const [clients, setClients] = useState([]);

  // Client logo data
  if (clients.length === 0) {
    axios
      .get(
        (process.env.REACT_APP_SERVER || "").replace(/\/$/, "") +
          "/api/clientList/",
      )
      .then((data) => {
        setClients(data["data"]["data"]);
      })
      .catch((error) => console.log(error));
  }

  return (
    <div className="my-10">
      {/* Heading */}
      <div className="box h-[5rem] w-full max-w-[20rem] sm:max-w-[25rem] relative flex justify-start items-start ml-[1.5rem] sm:ml-[2rem] group">
        <div className="h-12 w-1.5 bg-[#004B95] absolute mr-[1rem] origin-left group-hover:w-[15rem] duration-300 group"></div>
        <p className="text-[24px] absolute font-bold text-[#004B95] mt-[0.5rem] ml-[1rem] group-hover:text-white group-hover:translate-x-5 duration-300">
          Our clients
        </p>
      </div>

      <p className="text-slate-600 dark:text-slate-400 text-sm sm:text-base md:text-lg font-medium ml-[2.5rem] sm:ml-[3rem] mr-6 sm:mr-12 -mt-[1.5rem] mb-8 font-poppins max-w-[90%] xl:max-w-[85%] leading-relaxed text-justify">
        Trusted by 35+ industrial clients nationwide. We manufacture and supply
        premium material handling equipment, custom warehouse lifts, stackers,
        and industrial handling systems tailored to streamline B2B logistics and
        manufacturing operations.
      </p>

      {/* Client logos container */}
      <div className="grid grid-cols-2 sm:grid-cols-4 md:grid-cols-6 lg:grid-cols-8 gap-4 sm:gap-6 ml-[1.5rem] sm:ml-[2rem] pr-[1.5rem] sm:pr-[2rem] justify-center items-center">
        {clients.map((item, index) => (
          <a
            href={item[2]}
            className="w-full h-20 lg:w-32 lg:h-20 flex justify-center items-center group p-3 lg:p-0"
            title={item[0]}
            key={index}
          >
            {/* Client logo */}
            <img
              src={
                (process.env.REACT_APP_SERVER || "").replace(/\/$/, "") +
                item[1]
              }
              alt={item[0]}
              title={item[0]}
              width="128"
              height="80"
              loading="lazy"
              className="w-full h-full object-contain scale-100 group-hover:scale-110 transition-all duration-300"
            />
          </a>
        ))}
      </div>
    </div>
  );
};

export default OurClients;
